using Tellma.Core.Analyzers.Tests.Infrastructure;

namespace Tellma.Core.Analyzers.Tests
{
    /// <summary>
    ///     Every rule holds in generated code too: a file marked auto-generated, as a scaffolder, a
    ///     client generator or a template writes it, gets the same diagnostics as hand-written code.
    /// </summary>
    public class GeneratedCodeTests
    {
        /// <summary>The header a generator writes at the top of its file, which marks the file as generated.</summary>
        private const string Header = """
            // <auto-generated/>
            #nullable enable

            """;

        /// <summary>TELLMA0001 in generated code.</summary>
        /// <returns>A task that completes when the check has passed.</returns>
        [Fact]
        public Task Ordinal_binding_is_refused_in_generated_code()
        {
            return AnalyzerHarness.VerifyAsync<OrdinalBindingAnalyzer>(Header + """
                using Microsoft.Data.SqlClient.Server;

                class Rows
                {
                    object Make(SqlMetaData[] columns) => {|TELLMA0001:new SqlDataRecord(columns)|};
                }
                """);
        }

        /// <summary>TELLMA0002 in generated code.</summary>
        /// <returns>A task that completes when the check has passed.</returns>
        [Fact]
        public Task The_tenant_context_is_refused_in_generated_code()
        {
            return AnalyzerHarness.VerifyAsync<TenantContextAnalyzer>(Header + """
                using Tellma.Core.Data;

                class Reports
                {
                    int Run(TellmaDbContext context) => {|TELLMA0002:context.SaveChanges()|};
                }
                """);
        }

        /// <summary>TELLMA0003 and TELLMA0006 in generated code.</summary>
        /// <returns>A task that completes when the check has passed.</returns>
        [Fact]
        public Task Raw_statements_and_owned_writes_are_refused_in_generated_code()
        {
            return AnalyzerHarness.VerifyAsync<DataBatchAnalyzer>(Header + """
                using Tellma.Core.Abstractions.Data;
                using Tellma.Core.Abstractions.Jobs;

                class Client
                {
                    void Run(IDataBatch batch)
                    {
                        _ = batch.Sql($"{|TELLMA0003:MERGE INTO [dist].[Ledger] AS t USING (SELECT 1 AS [Id]) AS s ON t.[Id] = s.[Id] WHEN MATCHED THEN DELETE;|}", SqlOptions.None);
                        _ = {|TELLMA0006:batch.Save<Job>([])|};
                    }
                }
                """);
        }

        /// <summary>TELLMA0004 in generated code.</summary>
        /// <returns>A task that completes when the check has passed.</returns>
        [Fact]
        public Task Action_calls_are_refused_in_generated_code()
        {
            return AnalyzerHarness.VerifyAsync<ActionCallAnalyzer>(Header + """
                using System.Threading.Tasks;
                using Tellma.Core.Abstractions.Crud;

                public class Centers
                {
                    [ApiAction("export")]
                    public Task<int> ExportAsync(string format) => Task.FromResult(0);
                }

                class Client
                {
                    Task<int> Run(Centers centers) => {|TELLMA0004:centers.ExportAsync("csv")|};
                }
                """);
        }

        /// <summary>TELLMA0005 in generated code.</summary>
        /// <returns>A task that completes when the check has passed.</returns>
        [Fact]
        public Task Nested_pipelines_are_refused_in_generated_code()
        {
            return AnalyzerHarness.VerifyAsync<NestedPipelineAnalyzer>(Header + """
                using System.Collections.Generic;
                using System.Threading.Tasks;
                using Tellma.Core.Abstractions.Crud;
                using Tellma.Core.Abstractions.Entities;

                public class Center : TopLevelEntity;

                public class Unit : TopLevelEntity;

                public class UnitService : EntityService<Unit>;

                public class CenterRules(UnitService units) : IEntityValidator<Center>
                {
                    public Task ValidateAsync(IReadOnlyList<Center> entities) => {|TELLMA0005:units.SaveAsync([])|};
                }
                """);
        }
    }
}
